import React from "react";
import "../css/WhyChooseUs.css";

function WhyChooseUs() {
  const features = [
    {
      icon: "🚚",
      title: "Fast & Safe Delivery",
      description:
        "Get your healthcare essentials delivered safely and conveniently to your doorstep.",
    },
    {
      icon: "✓",
      title: "100% Genuine Products",
      description:
        "We provide trusted and quality healthcare products for your peace of mind.",
    },
    {
      icon: "🩺",
      title: "Expert Healthcare Support",
      description:
        "Get helpful support and guidance whenever you need assistance with your order.",
    },
    {
      icon: "🔒",
      title: "Secure & Easy Payment",
      description:
        "Enjoy a smooth and secure checkout experience with convenient payment options.",
    },
  ];

  return (
    <section className="why-section">
      <div className="why-container">

        <div className="why-heading">
          <p className="why-tag">✦ WHY CHOOSE US</p>

          <h2>
            Healthcare You Can
            <span> Trust.</span>
          </h2>

          <p>
            We make your healthcare journey easier by providing quality
            products, reliable service, and a convenient shopping experience.
          </p>
        </div>

        <div className="features-grid">
          {features.map((feature, index) => (
            <div className="feature-card" key={index}>

              <div className="feature-icon">
                {feature.icon}
              </div>

              <h3>{feature.title}</h3>

              <p>{feature.description}</p>

              <span className="feature-line"></span>

            </div>
          ))}
        </div>

      </div>
    </section>
  );
}

export default WhyChooseUs;
